/* ---------- 工具函数 ---------- */
const $ = sel => document.querySelector(sel);
const app = $("#app");
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hueOf = id => (id * 53) % 360;
const grad = id => `linear-gradient(135deg, hsl(${hueOf(id)},55%,34%), hsl(${(hueOf(id)+35)%360},62%,15%))`;
const hueOfName = n => { let h=0; for(const c of n) h=(h*31+c.charCodeAt(0))%360; return h; };
/* 头像内容：本地上传为 data:/http(s) 图片地址 → 渲染 <img>；预设表情/文字直接显示；无则默认 👤 */
function avatarInner(u){
  const a = u && u.avatar;
  if (a && (a.startsWith("data:") || /^https?:/i.test(a))) return `<img src="${a}" alt="头像">`;
  return a ? esc(a) : "👤";
}

/* 应用图片优先级：本地官方图（posters/local.js 登记，同域零防盗链风险） > 现场生成的“类海报”占位图（零版权风险、离线可显示）。
   注：B 站热链封面（POSTER_MAP）已于 2026-10-19 清空——版权电影的官方海报/剧照受版权保护，网上无合法免授权版本；
   故全站统一使用原创生成式 SVG 类海报。如需某部影片的真实授权剧照，请放入 posters/<id>.jpg 并在 posters/local.js 登记。 */
MOVIE_DATA.forEach(m => {
  const local = (window.MY_LOCAL_POSTERS && window.MY_LOCAL_POSTERS[m.id]);
  const p = local || POSTER_MAP[m.title];
  if (p){
    if (!m.poster) m.poster = p;
    if (!m.still)  m.still  = p;
  }
  if (!m.poster) m.poster = makePosterPlaceholder(m, false);  // 竖版（卡片/海报）
  if (!m.still)  m.still  = makePosterPlaceholder(m, true);   // 横版（详情/背景）
});

/* 背景样式：图片叠加在渐变之上——有图显示图片，图加载失败自动露出底部渐变占位 */
function bgStyle(m, useStill){
  const url = useStill ? (m.still || m.poster) : m.poster;
  const g = grad(m.id);
  if (url) return `background-image:url('${esc(url)}'),${g};background-size:cover,cover;background-position:center,center;background-repeat:no-repeat,no-repeat;`;
  return `background:${g}`;
}

/* SVG 文本转义 + CJK 自动换行（按字符断行） */
function svgEsc(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function wrapText(text, max){
  const out=[]; let line="";
  for(const ch of String(text)){
    line += ch;
    if(line.length >= max){ out.push(line); line=""; }
  }
  if(line) out.push(line);
  return out;
}

/* ---------- 无版权风险的“类海报”占位图 ----------
   现场用 SVG 生成（不引用任何受版权保护的素材），因此零侵权风险、离线也能显示。
   构图：专属配色渐变 + 暗角 + 胶片颗粒 + 胶片齿孔 + 按影片主类型变化的主体图形
         + 片名（自动换行）/ 年份·地区 / 导演｜类型，使其看起来像一张为该片定制的海报。
   若要换成真实照片，把 URL 填进 POSTER_MAP，或在 posters/local.js 登记本地官方图即可，本函数会自动让位。 */
/* 按影片主类型绘制一张“分类相关”的主题插画（纯 SVG，零版权、离线可显示）。
   顶部徽标由 makePosterPlaceholder 叠加，这里只负责中部主体图形。 */
function genreMotif(st, cx, cy, s, wide){
  const sw = s * 0.012 + 2;
  const W = `stroke="#fff" stroke-opacity=".5" fill="none" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"`;
  const F = `fill="#fff" fill-opacity=".42"`;
  switch(st){
    case "动画": return `<g ${W}><circle cx="${cx}" cy="${cy}" r="${s*0.2}"/><circle cx="${cx}" cy="${cy}" r="${s*0.32}" stroke-dasharray="${s*0.05} ${s*0.045}"/></g>`
      + `<g ${F}><circle cx="${cx-s*0.07}" cy="${cy-s*0.03}" r="${s*0.022}"/><circle cx="${cx+s*0.07}" cy="${cy-s*0.03}" r="${s*0.022}"/></g>`
      + `<path d="M ${cx-s*0.12} ${cy+s*0.08} Q ${cx} ${cy+s*0.16} ${cx+s*0.12} ${cy+s*0.08}" ${W}/>`;
    case "科幻": return `<g ${W}><ellipse cx="${cx}" cy="${cy}" rx="${s*0.34}" ry="${s*0.12}" transform="rotate(-18 ${cx} ${cy})"/>`
      + `<ellipse cx="${cx}" cy="${cy}" rx="${s*0.23}" ry="${s*0.08}" transform="rotate(26 ${cx} ${cy})"/></g>`
      + `<circle cx="${cx+s*0.2}" cy="${cy-s*0.12}" r="${s*0.06}" ${F}/>`
      + `<g ${F}>${Array.from({length:12},(_,i)=>{const a=Math.PI*2*i/12,r=s*(0.34+(i%2)*0.03);return `<circle cx="${(cx+Math.cos(a)*r).toFixed(1)}" cy="${(cy+Math.sin(a)*r).toFixed(1)}" r="${s*0.007}"/>`;}).join("")}</g>`;
    case "爱情": return `<path d="M ${cx} ${cy+s*0.16} C ${cx-s*0.24} ${cy-s*0.05}, ${cx-s*0.08} ${cy-s*0.22}, ${cx} ${cy-s*0.02} C ${cx+s*0.08} ${cy-s*0.22}, ${cx+s*0.24} ${cy-s*0.05}, ${cx} ${cy+s*0.16} Z" ${F}/>`;
    case "犯罪":
    case "悬疑": return `<g ${W}>${Array.from({length:9},(_,i)=>`<line x1="${cx-s*0.3}" y1="${(cy-s*0.22+i*s*0.055).toFixed(1)}" x2="${cx+s*0.3}" y2="${(cy-s*0.22+i*s*0.055).toFixed(1)}"/>`).join("")}</g>`
      + `<circle cx="${cx+s*0.12}" cy="${cy-s*0.04}" r="${s*0.05}" ${F}/>`;
    case "战争":
    case "历史": return `<g ${W}><path d="M ${cx} ${cy-s*0.18} L ${cx+s*0.16} ${cy-s*0.02} L ${cx+s*0.1} ${cy+s*0.2} L ${cx-s*0.1} ${cy+s*0.2} L ${cx-s*0.16} ${cy-s*0.02} Z"/></g>`
      + `<path d="M ${cx} ${cy-s*0.1} L ${cx} ${cy+s*0.16}" ${W}/>`;
    case "喜剧": return `<g ${F}><circle cx="${cx}" cy="${cy-s*0.02}" r="${s*0.18}"/></g>`
      + `<g ${W}><path d="M ${cx-s*0.1} ${cy-s*0.05} a ${s*0.03} ${s*0.03} 0 1 0 ${s*0.06} 0 M ${cx+s*0.04} ${cy-s*0.05} a ${s*0.03} ${s*0.03} 0 1 0 ${s*0.06} 0"/></g>`
      + `<path d="M ${cx-s*0.09} ${cy+s*0.04} Q ${cx} ${cy+s*0.13} ${cx+s*0.09} ${cy+s*0.04}" ${W}/>`;
    case "动作": return `<path d="M ${cx+s*0.05} ${cy-s*0.22} L ${cx-s*0.16} ${cy+s*0.05} L ${cx-s*0.04} ${cy+s*0.05} L ${cx-s*0.12} ${cy+s*0.22} L ${cx+s*0.18} ${cy-s*0.06} L ${cx+s*0.05} ${cy-s*0.06} Z" ${F}/>`;
    case "恐怖": return `<path d="M ${cx} ${cy-s*0.18} a ${s*0.14} ${s*0.14} 0 1 0 ${s*0.001} 0 Z" ${F}/>`
      + `<g ${W}><circle cx="${cx-s*0.05}" cy="${cy-s*0.03}" r="${s*0.018}"/><circle cx="${cx+s*0.05}" cy="${cy-s*0.03}" r="${s*0.018}"/></g>`;
    case "奇幻":
    case "冒险": return `<g ${W}><path d="M ${cx} ${cy-s*0.2} L ${cx+s*0.14} ${cy+s*0.04} L ${cx+s*0.05} ${cy+s*0.04} L ${cx+s*0.2} ${cy+s*0.2} L ${cx-s*0.2} ${cy+s*0.2} L ${cx-s*0.05} ${cy+s*0.04} L ${cx-s*0.14} ${cy+s*0.04} Z"/></g>`;
    case "家庭": return `<g ${W}><path d="M ${cx-s*0.18} ${cy+s*0.18} L ${cx-s*0.18} ${cy-s*0.02} L ${cx} ${cy-s*0.2} L ${cx+s*0.18} ${cy-s*0.02} L ${cx+s*0.18} ${cy+s*0.18} Z"/></g>`
      + `<path d="M ${cx} ${cy-s*0.02} l ${s*0.06} ${s*0.06} l ${s*0.06} -${s*0.06} l -${s*0.06} ${s*0.06} l -${s*0.06} -${s*0.06} Z" ${F}/>`;
    case "音乐":
    case "歌舞": return `<g ${F}><circle cx="${cx-s*0.06}" cy="${cy+s*0.12}" r="${s*0.05}"/><circle cx="${cx+s*0.1}" cy="${cy+s*0.12}" r="${s*0.05}"/></g>`
      + `<g ${W}><rect x="${cx-s*0.12}" y="${cy-s*0.16}" width="${s*0.04}" height="${s*0.28}"/><rect x="${cx+s*0.06}" y="${cy-s*0.16}" width="${s*0.04}" height="${s*0.28}"/></g>`;
    case "武侠": return `<g ${W}><path d="M ${cx-s*0.22} ${cy+s*0.18} L ${cx+s*0.2} ${cy-s*0.2}"/><path d="M ${cx+s*0.2} ${cy-s*0.2} l -${s*0.06} ${s*0.01} l ${s*0.02} ${s*0.06} Z" ${F}/><circle cx="${cx-s*0.22}" cy="${cy+s*0.18}" r="${s*0.03}" ${F}/></g>`;
    default: return `<g ${W}><rect x="${cx-s*0.22}" y="${cy-s*0.16}" width="${s*0.44}" height="${s*0.32}" rx="${s*0.04}"/><line x1="${cx}" y1="${cy-s*0.16}" x2="${cx}" y2="${cy+s*0.16}"/><circle cx="${cx-s*0.11}" cy="${cy}" r="${s*0.05}"/><circle cx="${cx+s*0.11}" cy="${cy}" r="${s*0.05}"/></g>`;
  }
}

/* 把 SVG 字符串转成最稳的 data URI：base64 不含任何会破坏 CSS background 解析的字符
   （此前用 encodeURIComponent 直接拼，在部分浏览器里会让整条 background-image 声明失效，
   连带渐变兜底一起丢失，卡片变空白）。base64 形式 100% 安全。 */
function svgToDataUri(svg){
  try { return "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svg))); }
  catch(e){ return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg); }
}
function makePosterPlaceholder(m, wide){
  const w = wide ? 960 : 400, h = wide ? 540 : 600;
  const hue = hueOf(m.id), h2 = (hue + 35) % 360;
  const st = (m.styles && m.styles[0]) || "剧情";
  const cx = w / 2, cy = h / 2, s = Math.min(w, h);
  const motif = genreMotif(st, cx, cy, s, wide);
  const maxChars = wide ? 11 : 7;
  const lines = wrapText(m.title || "", maxChars).slice(0, wide ? 3 : 4);
  const tSize = wide ? 58 : 46;
  const lh = tSize * 1.18;
  const baseY = h * (wide ? 0.60 : 0.58);
  const titleSVG = lines.map((ln, i) => {
    const y = baseY - (lines.length - 1) * lh / 2 + i * lh;
    return `<text x="${cx}" y="${y}" font-size="${tSize}" font-weight="800" fill="#fff" text-anchor="middle" font-family="'PingFang SC','Microsoft YaHei',sans-serif" style="paint-order:stroke;stroke:rgba(0,0,0,.42);stroke-width:${tSize*0.07}px;">${svgEsc(ln)}</text>`;
  }).join("");
  const metaSize = wide ? 26 : 19;
  const metaY = baseY + (lines.length) * lh / 2 + (wide ? 34 : 30);
  const yr = `${m.year || ""}${m.region ? (" · " + m.region) : ""}`;
  const metaSVG = `<text x="${cx}" y="${metaY}" font-size="${metaSize}" fill="rgba(255,255,255,.96)" text-anchor="middle" font-family="'PingFang SC','Microsoft YaHei',sans-serif">${svgEsc(yr)}</text>`
    + `<text x="${cx}" y="${metaY + metaSize * 1.6}" font-size="${metaSize * 0.82}" fill="rgba(255,255,255,.74)" text-anchor="middle" font-family="'PingFang SC','Microsoft YaHei',sans-serif">${svgEsc((m.director || "") + " ｜ " + (m.styles || []).join("/"))}</text>`;
  const holes = Array.from({length: Math.floor(w/34)}, (_, i) =>
    `<rect x="${8 + i*34}" y="10" width="16" height="12" rx="3" fill="#000" fill-opacity=".42"/>` +
    `<rect x="${8 + i*34}" y="${h-22}" width="16" height="12" rx="3" fill="#000" fill-opacity=".42"/>`).join("");
  const badgeY = wide ? 46 : 40;
  const badge = `<g><rect x="${cx-96}" y="${badgeY-26}" width="192" height="52" rx="26" fill="rgba(0,0,0,.42)" stroke="rgba(255,255,255,.75)" stroke-width="2"/><text x="${cx}" y="${badgeY+9}" font-size="${wide?30:24}" font-weight="800" fill="#fff" text-anchor="middle" font-family="'PingFang SC','Microsoft YaHei',sans-serif">${svgEsc(st)}</text></g>`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">`
    + `<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">`
    + `<stop offset="0" stop-color="hsl(${hue},52%,46%)"/><stop offset=".5" stop-color="hsl(${(hue+30)%360},56%,30%)"/><stop offset="1" stop-color="hsl(${(hue+75)%360},60%,14%)"/></linearGradient>`
    + `<radialGradient id="v" cx="50%" cy="34%" r="85%">`
    + `<stop offset="0" stop-color="#fff" stop-opacity=".14"/><stop offset="1" stop-color="#000" stop-opacity=".5"/></radialGradient>`
    + `</defs>`
    + `<rect width="${w}" height="${h}" fill="url(#g)"/>${badge}${motif}${titleSVG}${metaSVG}`
    + `<rect width="${w}" height="${h}" fill="url(#v)"/>`
    + `${holes}</svg>`;
  return svgToDataUri(svg);
}

/* ---------- 全站背景：取电影宣传图（模糊 + 低透明度） ---------- */
function setBackground(m){
  const layer = document.getElementById("bgLayer");
  if (!layer) return;
  if (!m){ layer.style.backgroundImage = ""; return; }
  const url = m.still || m.poster;
  layer.style.backgroundImage = url ? `url('${url}')` : grad(m.id);
}

function sizeClass(rating){
  if (rating >= 9.5) return "size-large";
  if (rating >= 9.2) return "size-mid";
  return "size-small";
}

/* ---------- 状态（localStorage 持久化） ---------- */
const LS_KEY = "gys_state_v1";
let state = {
  theme: "day",
  favorites: [],          // 收藏电影 id
  history: [],            // 浏览记录 id（最近在前）
  comments: {},           // 评论：{ [电影id]: [ {id, nick, avatar, text, ts, likes, liked} ] }
  user: { avatar:null, nickname:"影迷一号", signature:"用电影丈量世界。", styles:[] }
};
/* localStorage 读写安全兜底：在沙箱 iframe / file:// 等被禁用时退回内存存储，
   避免因 setItem 抛错而中断后续渲染（否则会表现为“点卡片跳不了/删除无效”）。 */
const _memStore = {};
function lsGet(k){ try { return localStorage.getItem(k); } catch(e){ return (k in _memStore) ? _memStore[k] : null; } }
function lsSet(k,v){ try { localStorage.setItem(k, v); } catch(e){ _memStore[k] = v; } }

function loadState(){
  try { const s = JSON.parse(lsGet(LS_KEY)); if (s) state = Object.assign(state, s); } catch(e){}
}
function saveState(){ lsSet(LS_KEY, JSON.stringify(state)); }

let currentView = "recommend";
let prevView = "recommend";
let lastSearch = "";
let lastRecQuery = null;    // 已生成随机推荐的查询（避免每次输入重排闪烁）
let lastRecs = [];

/* ---------- 卡片 HTML 生成 ---------- */
function cardHTML(m, opts={}){
  const favorited = state.favorites.includes(m.id);
  const heart = `<button class="heart ${favorited?'on':''}" data-heart="${m.id}" title="收藏/取消收藏">${favorited?'♥':'♡'}</button>`;
  const trash = opts.trash ? `<button class="trash" data-trash="${m.id}" title="删除记录">🗑</button>` : "";
  return `
  <div class="pcard ${sizeClass(m.rating)}" data-id="${m.id}">
    <div class="poster" style="${bgStyle(m)}">
      <div class="ptitle">${esc(m.title)}</div>
    </div>
    <div class="prating">${m.rating.toFixed(1)}</div>
    ${heart}${trash}
    <div class="hover-info">
      <div class="hi-cat">${esc(m.styles.join(" / "))}</div>
      <div class="hi-dir">导演：${esc(m.director)}</div>
    </div>
  </div>`;
}

/* 分区（栏目）标题 + 封面头图：封面取该分区代表影片的海报，与里面卡片同一张图 */
function sectionHead(title, repMovie){
  const cover = repMovie
    ? `<div class="section-cover" style="${bgStyle(repMovie)}" title="${esc(repMovie.title)}"></div>`
    : "";
  return `<div class="section-head">${cover}<div class="section-label">${title}</div></div>`;
}

/* ---------- 视图：今日推荐 ---------- */
let recCache = null;   // 缓存推荐排序，避免点收藏时整片拼贴重排（看起来像卡片消失）
function buildRecommend(){
  const pool = [...MOVIE_DATA];
  const pref = state.user.styles;
  let ordered = pool;
  if (pref && pref.length){
    const matched = pool.filter(m => m.styles.some(s => pref.includes(s)));
    const rest = pool.filter(m => !m.styles.some(s => pref.includes(s)));
    // 洗牌后偏好项前置，保证偏向但不全是
    ordered = shuffle(matched).concat(shuffle(rest));
  } else {
    ordered = shuffle(pool);
  }
  const collage = ordered.slice(0, 14);
  const featured = ordered.find(m => m.rating >= 9.4) || ordered[0];
  recCache = { collage, featured };
}
function renderRecommend(force){
  if (force || !recCache) buildRecommend();
  const { collage, featured } = recCache;

  // 各分类推荐（稳定，不随收藏刷新而变动）
  const styleSections = ["剧情","科幻","动画","爱情","犯罪"];
  let sections = "";
  styleSections.forEach(st => {
    const list = MOVIE_DATA.filter(m => m.styles.includes(st)).slice(0, 8);
    if (!list.length) return;
    const rep = list.reduce((b,m) => m.rating > b.rating ? m : b, list[0]); // 评分最高者作封面
    sections += `${sectionHead(st + " · 精选推荐", rep)}
      <div class="hscroll">${list.map(m => cardHTML(m)).join("")}
        <button class="more-card" data-more-style="${esc(st)}" title="查看全部分类中的${st}电影">
          <span class="more-card-ico">＋</span>
          <span>查找更多<br>${st}电影</span>
        </button>
      </div>`;
  });

  setBackground(featured);
  app.innerHTML = `
    <div class="hero" data-hero="${featured.id}" title="查看《${esc(featured.title)}》详情" style="background:${bgStyle(featured)}">
      <div class="hero-content">
        <div class="hero-tag">今日高光 · 豆瓣高分</div>
        <div class="hero-title">${esc(featured.title)}</div>
        <div class="hero-meta">${featured.year} · ${esc(featured.region)} · ${featured.rating.toFixed(1)}分 · 导演 ${esc(featured.director)}</div>
        <div class="hero-enter">查看详情 →</div>
      </div>
    </div>
    ${sectionHead("高分拼贴（大小由评分决定 · 悬停查看分类与导演）", collage[0])}
    <div class="collage">${collage.map(m => cardHTML(m)).join("")}</div>
    ${sections}
    <div class="view-more-wrap">
      <button class="view-more-btn" id="viewMoreBtn">查看更多电影 →</button>
    </div>
  `;
}

function shuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; }

/* 搜索归一化：忽略标点/分隔符/空格，使“哈利波特”能命中“哈利·波特与魔法石” */
function norm(s){
  return (s||'').toLowerCase().replace(/[\s·・.、,，:：!！?？'’"“”()（）\[\]【】\-—_/\\|]/g, '');
}

/* ---------- 加权随机推荐：评分越高出现概率越大 ---------- */
function weightedRandomMovies(n){
  const pool = MOVIE_DATA.map(m => ({ m, w: Math.pow(m.rating, 5) }));
  const total = pool.reduce((s,x)=>s+x.w, 0);
  const out = [], used = new Set();
  let guard = 0;
  while (out.length < n && used.size < MOVIE_DATA.length && guard++ < 500){
    let r = Math.random()*total, pick = pool[pool.length-1];
    for (const x of pool){ if (r <= x.w){ pick = x; break; } r -= x.w; }
    if (!used.has(pick.m.id)){ used.add(pick.m.id); out.push(pick.m); }
  }
  return out;
}

/* ---------- 视图：分类 ---------- */
const YEAR_GROUPS = [
  { label:"1990年以前", test:y=>y<1990 },
  { label:"1990-1999",  test:y=>y>=1990&&y<=1999 },
  { label:"2000-2009",  test:y=>y>=2000&&y<=2009 },
  { label:"2010年以后", test:y=>y>=2010 }
];
let catFilters = { year:null, region:null, styles:[] };

function renderCategory(){
  const regions = [...new Set(MOVIE_DATA.map(m=>m.region))];
  const styles = [...new Set(MOVIE_DATA.flatMap(m=>m.styles))];

  const yearChips = YEAR_GROUPS.map(g =>
    `<button class="chip ${catFilters.year===g.label?'on':''}" data-year="${esc(g.label)}">${g.label}</button>`).join("");
  const regionChips = regions.map(r =>
    `<button class="chip ${catFilters.region===r?'on':''}" data-region="${esc(r)}">${r}</button>`).join("");
  const styleChips = styles.map(s =>
    `<button class="chip ${catFilters.styles.includes(s)?'on':''}" data-style="${esc(s)}">${s}</button>`).join("");

  // 过滤
  let result = MOVIE_DATA.filter(m => {
    if (catFilters.year && !YEAR_GROUPS.find(g=>g.label===catFilters.year).test(m.year)) return false;
    if (catFilters.region && m.region !== catFilters.region) return false;
    if (catFilters.styles.length && !catFilters.styles.every(s => m.styles.includes(s))) return false;
    return true;
  });

  const resultHTML = result.length
    ? `<div class="cat-result">${result.map(m=>cardHTML(m)).join("")}</div>`
    : `<div class="empty-tip">没有找到对应电影</div>`;

  app.innerHTML = `
    <h2 class="view-title">分类浏览</h2>
    <div class="filter-group"><h4>按年份</h4><div class="chips" id="yearChips">${yearChips}</div></div>
    <div class="filter-group"><h4>按地区</h4><div class="chips" id="regionChips">${regionChips}</div></div>
    <div class="filter-group"><h4>按风格（可多选）</h4><div class="chips" id="styleChips">${styleChips}</div></div>
    ${resultHTML}
  `;
}

