/* ---------- 个人空间：底部高分经典台词轮播（每 5 秒随机切换，栏目透明） ---------- */
let quoteTimer = null;
function showRandomQuote(b){
  if (!b || !MOVIE_QUOTES.length) return;
  let idx;
  do { idx = Math.floor(Math.random() * MOVIE_QUOTES.length); }
  while (MOVIE_QUOTES.length > 1 && MOVIE_QUOTES[idx].id === +b.dataset.qid);
  const q = MOVIE_QUOTES[idx];
  b.dataset.qid = q.id;
  b.dataset.id  = q.id;
  b.querySelector(".quote-text").textContent = q.text;
  b.querySelector(".quote-src").textContent = `《${q.movie}》 · ${q.rating} 分 · 点击进入影片`;
  b.classList.remove("q-in"); void b.offsetWidth; b.classList.add("q-in");
}
function startQuotes(){
  clearInterval(quoteTimer);
  const box = document.getElementById("quoteBox");
  if (!box || !MOVIE_QUOTES.length) return;
  showRandomQuote(box);                 // 立即显示第一条，无需等待 5 秒
  quoteTimer = setInterval(() => {
    const b = document.getElementById("quoteBox");
    if (!b){ clearInterval(quoteTimer); quoteTimer = null; return; }  // 离开页面后自转停
    showRandomQuote(b);
  }, 5000);
}

