/* ---------- 评论区 ---------- */
/* 评论审核：客户端敏感词过滤（纯前端、无后端；词库为示意，可随需扩充）。
   说明：静态站点无服务端，无法做语义级/人工审核，只能发布时做一次关键词匹配；
        命中即拦截不发表并弹出警告，累计警告次数持久化到本地。 */
const BAD_WORDS = [
  "傻逼","傻×","滚蛋","贱人","婊子","操你","草你","妈的","去死","废物",
  "裸聊","约炮","色情","淫","加微信","加我vx","加我微信","代购","私聊转账","兼职刷单","赌博"
];
function auditComment(text){
  const low = text.toLowerCase();
  for (const w of BAD_WORDS){
    if (low.indexOf(w.toLowerCase()) >= 0) return { ok:false, word:w };
  }
  return { ok:true };
}

function showWarn(msg){
  state.warnCount = (state.warnCount || 0) + 1;
  saveState();
  let t = document.getElementById("cmtWarn");
  if (!t){
    t = document.createElement("div");
    t.id = "cmtWarn";
    t.className = "warn-toast";
    document.body.appendChild(t);
  }
  const tail = state.warnCount > 1 ? `（累计警告 ${state.warnCount} 次，请文明发言）` : "（请文明发言）";
  t.textContent = "⚠️ " + msg + tail;
  t.classList.add("show");
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove("show"), 3400);
}

function commentsHTML(movieId){
  const u = state.user;
  const myAva = u.avatar ? `<img src="${u.avatar}" alt="">` : "👤";
  const list = state.comments[movieId] || [];
  return `
    <div class="comments" id="comments" data-mid="${movieId}">
      <h3 class="cmt-title">💬 评论区 <span class="cmt-count" id="cmtCount">${list.length}</span></h3>
      <div class="cmt-form">
        <div class="cmt-ava">${myAva}</div>
        <div class="cmt-input-wrap">
          <textarea id="cmtInput" maxlength="300" placeholder="文明发言，友善评论…（最多 300 字，Ctrl+Enter 快速发布）"></textarea>
          <div class="cmt-form-foot">
            <span class="cmt-as">以「${esc(u.nickname||"影迷一号")}」身份发布</span>
            <button class="cmt-submit" id="cmtSubmit" type="button">发布评论</button>
          </div>
        </div>
      </div>
      <div class="cmt-list" id="cmtList">${list.length ? list.map(commentItemHTML).join("") : '<div class="cmt-empty">还没有评论，来做第一个评论的人吧～</div>'}</div>
    </div>`;
}

function commentItemHTML(c){
  const ava = c.avatar ? `<img src="${c.avatar}" alt="">` : "👤";
  return `
    <div class="cmt-item" data-cid="${c.id}">
      <div class="cmt-ava">${ava}</div>
      <div class="cmt-body">
        <div class="cmt-head">
          <span class="cmt-nick">${esc(c.nick)}</span>
          <span class="cmt-time">${formatCmtTime(c.ts)}</span>
        </div>
        <div class="cmt-text">${esc(c.text)}</div>
        <button class="cmt-like ${c.liked?'on':''}" data-cid="${c.id}" type="button">👍 <span class="cmt-like-count">${c.likes}</span></button>
      </div>
    </div>`;
}

function formatCmtTime(ts){
  const d = new Date(ts), now = Date.now(), diff = (now-ts)/1000;
  if (diff < 60) return "刚刚";
  if (diff < 3600) return Math.floor(diff/60) + " 分钟前";
  if (diff < 86400) return Math.floor(diff/3600) + " 小时前";
  const p = n => (n<10 ? "0" : "") + n;
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`;
}

function rerenderComments(mid){
  const list = state.comments[mid] || [];
  const wrap = $("#cmtList");
  if (wrap) wrap.innerHTML = list.length
    ? list.map(commentItemHTML).join("")
    : `<div class="cmt-empty">还没有评论，来做第一个评论的人吧～</div>`;
  const cnt = $("#cmtCount"); if (cnt) cnt.textContent = list.length;
}

function submitComment(){
  const wrap = $("#comments"); if (!wrap) return;
  const mid = +wrap.dataset.mid;
  const input = $("#cmtInput"); if (!input) return;
  const text = input.value.trim();
  if (!text){ input.focus(); return; }
  const r = auditComment(text);
  if (!r.ok){
    showWarn("你的评论包含不当内容，已被系统审核拦截，未能发表。");
    input.focus();
    return;
  }
  if (!state.comments[mid]) state.comments[mid] = [];
  const u = state.user;
  state.comments[mid].unshift({
    id: Date.now() + "_" + Math.floor(Math.random()*1000),
    nick: u.nickname || "影迷一号",
    avatar: u.avatar || null,
    text,
    ts: Date.now(),
    likes: 0,
    liked: false
  });
  saveState();
  input.value = "";
  rerenderComments(mid);
}

function toggleLikeComment(cid){
  const wrap = $("#comments"); if (!wrap) return;
  const mid = +wrap.dataset.mid;
  const list = state.comments[mid] || [];
  const c = list.find(x => x.id === cid);
  if (!c) return;
  if (c.liked){ c.liked = false; c.likes = Math.max(0, c.likes - 1); }
  else { c.liked = true; c.likes += 1; }
  saveState();
  // 局部更新该条点赞按钮，避免整段重绘导致输入框失焦
  const btn = document.querySelector(`.cmt-like[data-cid="${cid}"]`);
  if (btn){ btn.classList.toggle("on", c.liked); const n = btn.querySelector(".cmt-like-count"); if (n) n.textContent = c.likes; }
}

/* ---------- 弹窗 ---------- */
function openModal(bodyHtml, actions){
  $("#modalBody").innerHTML = bodyHtml;
  const act = $("#modalActions"); act.innerHTML = "";
  actions.forEach(a => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = a.label;
    b.className = a.cls || "";
    b.onclick = a.onClick;
    act.appendChild(b);
  });
  $("#modalMask").classList.remove("hidden");
}
function closeModal(){ $("#modalMask").classList.add("hidden"); }

function showPerson(name){
  const works = MOVIE_DATA.filter(m => m.director===name || (m.actors||[]).includes(name));
  const isDir = works.some(m => m.director===name);
  const role = isDir ? "导演" : "演员";
  // 从该人物参演/执导作品的奖项推导（与片库数据天然一致，避免遗漏）
  const derived = [], seen = new Set();
  works.forEach(m => {
    (m.awards||[]).forEach(a => {
      const key = a + "@" + m.title;
      if (!seen.has(key)){ seen.add(key); derived.push(`${a}（${m.title}）`); }
    });
  });
  const personal = PERSON_AWARDS[name];
  let awards;
  if (personal && derived.length) awards = personal + "　本片库作品奖项：" + derived.join("、");
  else if (personal)             awards = personal;
  else if (derived.length)       awards = derived.join("、");
  else                           awards = "暂无主要奖项记录（作品见下）。";
  openModal(
    `<div style="font-size:18px;font-weight:700;margin-bottom:6px">${esc(name)}</div>
     <div style="color:var(--text-soft);font-size:13px;margin-bottom:10px">身份：${role}</div>
     <div class="person-works"><b>参与作品：</b>${works.map(w=>esc(w.title)).join("、")}</div>
     <div class="person-works" style="margin-top:8px"><b>主要奖项：</b>${esc(awards)}</div>`,
    [{ label:"关闭", cls:"btn-no", onClick:closeModal }]
  );
}

/* ---------- 视图路由 ---------- */
/* 视图切换的透明过渡：淡出 .5s + 切换内容 + 淡入 .5s，共约 1 秒 */
function navigateWithFade(renderFn){
  app.classList.add("fading");                 // #app 透明度 → 0（约 .5s）
  setTimeout(() => {
    renderFn();                                // 完全透明时替换内容
    window.scrollTo(0,0);
    setTimeout(() => app.classList.remove("fading"), 50);  // 透明度 → 1（约 .5s）
  }, 500);
}

function showView(view){
  clearInterval(quoteTimer);            // 离开个人空间时停止台词轮播，避免定时器泄漏
  currentView = view;
  prevView = view;
  document.querySelectorAll(".nav-btn").forEach(b => b.classList.toggle("active", b.dataset.view===view));
  navigateWithFade(() => {
    if (view==="recommend") renderRecommend(true);
    else if (view==="category") renderCategory();
    else if (view==="history") renderHistory();
    else if (view==="favorite") renderFavorite();
    else if (view==="space") renderSpace();
  });
}

/* ---------- 事件绑定 ---------- */
function bindEvents(){
  // 导航
  document.querySelectorAll(".nav-btn").forEach(b => b.addEventListener("click", () => showView(b.dataset.view)));

  // 主题切换
  $("#themeBtn").addEventListener("click", () => {
    state.theme = state.theme==="day" ? "night" : "day";
    applyTheme();
    saveState();
  });

  // 搜索（按钮 / 回车 → 带透明过渡；输入实时过滤 → 即时）
  $("#searchBtn").addEventListener("click", () => runSearch($("#searchInput").value, true));
  $("#searchInput").addEventListener("keydown", e => { if (e.key==="Enter") runSearch($("#searchInput").value, true); });
  $("#searchInput").addEventListener("input", e => runSearch(e.target.value));

  // 主内容区事件委托
  app.addEventListener("click", e => {
    const heart = e.target.closest("[data-heart]");
    if (heart){ e.stopPropagation(); toggleFavorite(+heart.dataset.heart); return; }
    const trash = e.target.closest("[data-trash]");
    if (trash){ e.stopPropagation(); confirmDelete(+trash.dataset.trash); return; }
    const person = e.target.closest("[data-person]");
    if (person){ showPerson(person.dataset.person); return; }
    const back = e.target.closest("#backBtn");
    if (back){ showView(prevView); return; }

    // 详情页评论区：发布评论 / 点赞
    const cmtSubmit = e.target.closest("#cmtSubmit");
    if (cmtSubmit){ submitComment(); return; }
    const cmtLike = e.target.closest(".cmt-like");
    if (cmtLike){ toggleLikeComment(cmtLike.dataset.cid); return; }

    // 个人空间：经典台词卡片 → 跳转到对应高分电影详情
    const quote = e.target.closest("#quoteBox");
    if (quote && quote.dataset.id){ openDetail(+quote.dataset.id); return; }
    // 今日推荐顶部 Hero（最大栏目，今日高光影片）→ 跳转详情
    const hero = e.target.closest("[data-hero]");
    if (hero){ openDetail(+hero.dataset.hero); return; }

    const card = e.target.closest(".pcard");
    if (card){ openDetail(+card.dataset.id); return; }

    // 今日推荐「查看更多」→ 跳转到分类
    if (e.target.closest("#viewMoreBtn")){ showView("category"); return; }

    // 今日推荐各栏目「查找更多」→ 跳到分类页并自动应用该风格筛选
    const moreBtn = e.target.closest("[data-more-style]");
    if (moreBtn){
      catFilters = { year:null, region:null, styles:[moreBtn.dataset.moreStyle] };
      showView("category");
      return;
    }

    // 分类筛选 chips
    const yc = e.target.closest("[data-year]");
    if (yc){ catFilters.year = catFilters.year===yc.dataset.year ? null : yc.dataset.year; renderCategory(); return; }
    const rc = e.target.closest("[data-region]");
    if (rc){ catFilters.region = catFilters.region===rc.dataset.region ? null : rc.dataset.region; renderCategory(); return; }
    const sc = e.target.closest("[data-style]");
    if (sc){ const s=sc.dataset.style; const i=catFilters.styles.indexOf(s); i>=0?catFilters.styles.splice(i,1):catFilters.styles.push(s); renderCategory(); return; }

    // 个人空间：风格兴趣
    const pset = e.target.closest("[data-pset]");
    if (pset){ const s=pset.dataset.pset; const i=state.user.styles.indexOf(s); i>=0?state.user.styles.splice(i,1):state.user.styles.push(s); saveState(); renderSpace(); return; }

    // 个人空间：保存资料
    if (e.target.id==="saveProfile"){
      state.user.nickname = $("#nickInput").value.trim() || "影迷一号";
      state.user.signature = $("#signInput").value.trim().slice(0,30);
      saveState(); renderSpace(); return;
    }
  });

  // 签名字数实时统计
  app.addEventListener("input", e => {
    if (e.target.id==="signInput"){ $("#signCount").textContent = e.target.value.length; }
  });

  // 个人空间：头像上传（文件选择触发 change）
  app.addEventListener("change", e => {
    if (e.target.id==="avatarInput"){
      const file = e.target.files[0];
      if (file){ const r=new FileReader(); r.onload=ev=>{ state.user.avatar=ev.target.result; saveState(); renderSpace(); }; r.readAsDataURL(file); }
    }
  });

  // 评论区：Ctrl/⌘ + Enter 快速发布
  app.addEventListener("keydown", e => {
    if (e.target.id==="cmtInput" && e.key==="Enter" && (e.ctrlKey || e.metaKey)){
      e.preventDefault(); submitComment();
    }
  });

  // 弹窗遮罩点击关闭
  $("#modalMask").addEventListener("click", e => { if (e.target.id==="modalMask") closeModal(); });

  // 登录 / 欢迎界面事件委托
  const loginScreen = document.getElementById("loginScreen");
  loginScreen.addEventListener("click", e => {
    if (e.target.closest("[data-login-enter]")){ renderLoginForm(); return; }
    if (e.target.closest("[data-login-back]")){ renderLogin(); return; }
    const ava = e.target.closest("[data-ava]");
    if (ava){
      loginAvatar = ava.dataset.ava;
      const prev = loginScreen.querySelector(".login-avatar-preview");
      if (prev) prev.innerHTML = avatarInner({ avatar:loginAvatar });
      loginScreen.querySelectorAll(".presel-ava").forEach(b => b.classList.toggle("on", b.dataset.ava===loginAvatar));
      return;
    }
    const lp = e.target.closest("[data-lpref]");
    if (lp){
      const s = lp.dataset.lpref;
      const i = loginPrefs.indexOf(s);
      if (i>=0){ loginPrefs.splice(i,1); lp.classList.remove("on"); }
      else { loginPrefs.push(s); lp.classList.add("on"); }
      return;
    }
    if (e.target.id==="loginSave"){ submitLogin(); return; }
  });
  loginScreen.addEventListener("change", e => {
    if (e.target.id==="loginAvatarInput"){
      const file = e.target.files[0];
      if (file){
        const r = new FileReader();
        r.onload = ev => {
          loginAvatar = ev.target.result;
          const prev = loginScreen.querySelector(".login-avatar-preview");
          if (prev) prev.innerHTML = avatarInner({ avatar:loginAvatar });
          loginScreen.querySelectorAll(".presel-ava").forEach(b => b.classList.remove("on"));
        };
        r.readAsDataURL(file);
      }
    }
  });
}

function runSearch(q, animate){
  lastSearch = q;
  currentView = "search";
  prevView = "search";
  document.querySelectorAll(".nav-btn").forEach(b=>b.classList.remove("active"));
  if (animate) navigateWithFade(() => renderSearch(q));
  else renderSearch(q);   // 输入实时过滤：即时切换，不走淡入淡出
}

function toggleFavorite(id){
  const i = state.favorites.indexOf(id);
  if (i>=0) state.favorites.splice(i,1); else state.favorites.push(id);
  saveState();
  // 局部刷新当前视图，保持心形状态
  refreshCurrent();
}
function confirmDelete(id){
  openModal(`<div>是否要删除该电影记录？</div>`, [
    { label:"否", cls:"btn-no", onClick:closeModal },
    { label:"是", cls:"btn-yes", onClick:()=>{ state.history = state.history.filter(h=>h!==id); closeModal(); renderHistory(); saveState(); } }
  ]);
}
function openDetail(id){
  // 记录历史（去重，最近在前）
  state.history = [id, ...state.history.filter(h=>h!==id)].slice(0, 50);
  navigateWithFade(() => renderDetail(id));
  saveState();
}

function refreshCurrent(){
  if (currentView==="recommend") renderRecommend(false);
  else if (currentView==="category") renderCategory();
  else if (currentView==="history") renderHistory();
  else if (currentView==="favorite") renderFavorite();
  else if (currentView==="space") renderSpace();
  else if (currentView==="search") renderSearch(lastSearch);
}

function applyTheme(){
  document.body.classList.toggle("night", state.theme==="night");
  $("#themeBtn").textContent = state.theme==="day" ? "☀" : "🌙";
}

/* ---------- 登录 / 欢迎界面（匿名游客进入） ---------- */
let loginAvatar = null;     // 临时头像（emoji 字符串 或 dataURL）
let loginPrefs = [];        // 临时偏好数组

function renderLogin(){
  const screen = document.getElementById("loginScreen");
  screen.classList.remove("hidden");
  screen.innerHTML = `
    <div class="login-card">
      <div class="login-logo">🎬</div>
      <h1 class="login-title">影视资源库</h1>
      <p class="login-tagline">聚合五大视频平台 · 发现你的下一部好电影</p>
      <div class="login-desc">
        这里帮你一站式检索 <b>哔哩哔哩 / 腾讯视频 / 爱奇艺 / 优酷 / 芒果TV</b> 的电影资源：<br>
        · 每日高分推荐与今日高光影片<br>
        · 按地区、年份、风格分类浏览<br>
        · 自动记录观看历史与个人收藏<br>
        · 依据你的偏好智能偏向今日推荐<br>
        · 一键跳转各平台观看，附收费模式说明<br>
        · 高分经典台词每日轮播
      </div>
      <button class="login-enter" data-login-enter>游客进入 →</button>
      <p class="login-foot">无需注册，以匿名身份畅享全部功能</p>
    </div>`;
}

function renderLoginForm(){
  const screen = document.getElementById("loginScreen");
  const styleOptions = [...new Set(MOVIE_DATA.flatMap(m=>m.styles))];
  loginPrefs = [...state.user.styles];
  const preset = ["🎬","🍿","🐱","🌟","🦊","🚀","🎭","🌈","🐼","⚡"];
  screen.innerHTML = `
    <div class="login-card login-form">
      <button class="login-back" data-login-back>← 返回</button>
      <h2 class="login-title sm">完善你的匿名资料</h2>
      <p class="login-sub">这些信息仅用于个性化推荐，并以匿名方式保存在本机。</p>

      <div class="login-field">
        <label>匿名昵称</label>
        <input type="text" id="loginNick" value="${esc(state.user.nickname==="影迷一号"?"":state.user.nickname)}" placeholder="例如：夜行观影人" maxlength="20">
      </div>

      <div class="login-field">
        <label>选择头像</label>
        <div class="login-avatar-row">
          <div class="login-avatar-preview avatar">${loginAvatar ? avatarInner({avatar:loginAvatar}) : "👤"}</div>
          <div class="preset-avas">${preset.map(e=>`<button type="button" class="presel-ava" data-ava="${e}">${e}</button>`).join("")}</div>
        </div>
        <label class="avatar-btn login-upload" for="loginAvatarInput">上传图片</label>
        <input type="file" id="loginAvatarInput" accept="image/*" hidden>
      </div>

      <div class="login-field">
        <label>个人偏好（可多选，影响今日推荐）</label>
        <div class="chips" id="loginPrefs">${styleOptions.map(s=>`<button type="button" class="chip ${loginPrefs.includes(s)?'on':''}" data-lpref="${esc(s)}">${s}</button>`).join("")}</div>
      </div>

      <button class="login-enter" id="loginSave">保存并进入影视库</button>
    </div>`;
}

function submitLogin(){
  const nick = document.getElementById("loginNick").value.trim();
  state.user.nickname = nick || "影迷一号";
  state.user.avatar = loginAvatar || null;
  state.user.styles = [...loginPrefs];
  state.user.setup = true;
  saveState();
  const screen = document.getElementById("loginScreen");
  screen.classList.add("hidden");
  screen.innerHTML = "";
  showView("recommend");
}

/* ---------- 初始化 ---------- */
function init(){
  loadState();
  applyTheme();
  bindEvents();
  if (!state.user.setup){ renderLogin(); }
  else { showView("recommend"); }
}
init();
